// audio.js — Sistem Audio Scanner PDC
// File ini berisi base64 audio dan fungsi playScanner

// SISTEM AUDIO SCANNER — base64 OGG files
    // =============================================
    const SCAN_AUDIO_B64 = {
      cancel      : '',
      double      : '',
      valid       : '',
      tidak_valid : ''
    };

    // Preload semua audio jadi URL
    const SCAN_AUDIO_URLS = {};
    (function() {
      for (const [k, v] of Object.entries(SCAN_AUDIO_B64)) {
        const bin = atob(v), buf = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
        SCAN_AUDIO_URLS[k] = URL.createObjectURL(new Blob([buf], { type: 'audio/ogg' }));
      }
    })();

    function playScanner(name) {
      return new Promise(resolve => {
        const audio = new Audio(SCAN_AUDIO_URLS[name]);
        audio.volume = 1.0;
        audio.onended = resolve;
        audio.onerror = resolve;
        audio.play().catch(resolve);
        setTimeout(resolve, 5000);
      });
    }

    function speak(text, opts) {
      opts = opts || {};
      return new Promise(function(resolve) {
        if (!window.speechSynthesis) { resolve(); return; }
        speechSynthesis.cancel();
        const utt = new SpeechSynthesisUtterance(text);
        utt.lang = 'id-ID';
        utt.rate = opts.rate || 1.0;
        utt.pitch = opts.pitch || 1.3;
        utt.volume = 1;
        const voices = speechSynthesis.getVoices();
        const idVoice = voices.find(function(v) { return v.lang && v.lang.startsWith('id'); });
        if (idVoice) utt.voice = idVoice;
        utt.onend = resolve;
        utt.onerror = resolve;
        speechSynthesis.speak(utt);
        setTimeout(resolve, 4000);
      });
    }

    async function speakParts(parts, opts) {
      for (let i = 0; i < parts.length; i++) {
        await speak(parts[i], opts);
        if (i < parts.length - 1) await new Promise(function(r) { setTimeout(r, (opts && opts.gap) || 0); });
      }
    }

    function beepClean(freq, dur, vol, t) {
      const ctx = getAudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(masterGain);
      osc.type = 'sine';
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0, t);
      gain.gain.linearRampToValueAtTime(vol, t + 0.006);
      gain.gain.setValueAtTime(vol, t + dur * 0.7);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.start(t); osc.stop(t + dur + 0.01);
    }

    function warningTone() {
      return new Promise(function(resolve) {
        const ctx = getAudioCtx();
        const t = ctx.currentTime;
        beepClean(880, 0.10, 0.9, t);
        beepClean(880, 0.10, 0.9, t + 0.13);
        setTimeout(resolve, 260);
      });
    }

    function tettKeras() {
      return new Promise(function(resolve) {
        const ctx = getAudioCtx();
        const t = ctx.currentTime;
        const sub = ctx.createOscillator();
        const subG = ctx.createGain();
        sub.connect(subG); subG.connect(masterGain);
        sub.type = 'sine';
        sub.frequency.setValueAtTime(110, t);
        sub.frequency.exponentialRampToValueAtTime(55, t + 0.18);
        subG.gain.setValueAtTime(0, t);
        subG.gain.linearRampToValueAtTime(1.0, t + 0.005);
        subG.gain.setValueAtTime(1.0, t + 0.06);
        subG.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
        sub.start(t); sub.stop(t + 0.24);
        const sq = ctx.createOscillator();
        const sqG = ctx.createGain();
        const ws = ctx.createWaveShaper();
        const curve = new Float32Array(256);
        for (let i = 0; i < 256; i++) {
          const x = (i * 2) / 256 - 1;
          curve[i] = (Math.PI + 200) * x / (Math.PI + 200 * Math.abs(x));
        }
        ws.curve = curve;
        sq.connect(ws); ws.connect(sqG); sqG.connect(masterGain);
        sq.type = 'square';
        sq.frequency.value = 260;
        sqG.gain.setValueAtTime(0, t);
        sqG.gain.linearRampToValueAtTime(0.9, t + 0.003);
        sqG.gain.setValueAtTime(0.9, t + 0.10);
        sqG.gain.linearRampToValueAtTime(0.0001, t + 0.14);
        sq.start(t); sq.stop(t + 0.15);
        const bufSize = Math.floor(ctx.sampleRate * 0.025);
        const buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
        const data = buf.getChannelData(0);
        for (let i = 0; i < bufSize; i++) data[i] = Math.random() * 2 - 1;
        const noise = ctx.createBufferSource();
        noise.buffer = buf;
        const nG = ctx.createGain();
        const nFilt = ctx.createBiquadFilter();
        nFilt.type = 'lowpass'; nFilt.frequency.value = 600;
        noise.connect(nFilt); nFilt.connect(nG); nG.connect(masterGain);
        nG.gain.setValueAtTime(0.9, t);
        nG.gain.exponentialRampToValueAtTime(0.0001, t + 0.025);
        noise.start(t); noise.stop(t + 0.03);
        setTimeout(resolve, 280);
      });
    }

    // Inisialisasi voices saat halaman load
    speechSynthesis.getVoices();
    if (speechSynthesis.onvoiceschanged !== undefined) {
      speechSynthesis.onvoiceschanged = function() { speechSynthesis.getVoices(); };
    }

    // Fungsi utama yang dipanggil saat scan
    async function playScanVoice(type) {
      try {
        if (type === 'cancel')      await playScanner('cancel');
        else if (type === 'double') await playScanner('double');
        else if (type === 'valid')  await playScanner('valid');
        else if (type === 'tidak_valid') await playScanner('tidak_valid');
      } catch(e) { /* abaikan jika browser tidak support */ }
    }

    function handleCancelScan(event) {
      if (event.key !== 'Enter') return;
      const input = document.getElementById('cancel-scan-input');
      const resi  = input.value.trim().toUpperCase();
      input.value = '';
      if (!resi) return;

      const resultBox = document.getElementById('cancel-last-result');

      // Cek apakah resi JNT (awalan JY atau JX)
      const isJNT = resi.startsWith('JY') || resi.startsWith('JX');
      if (!isJNT) {
        playScanVoice('tidak_valid');
        resultBox.innerHTML = `
          <div style="text-align:center;">
            <div style="font-size:28px;margin-bottom:4px;">🚫</div>
            <div style="font-size:15px;font-weight:800;color:#be123c;">Bukan Paket JNT</div>
            <div style="font-size:12px;color:#94a3b8;margin-top:4px;font-family:monospace;">${resi}</div>
          </div>`;
        resultBox.style.background = '#fff1f2';
        resultBox.style.border     = '1.5px solid #fecdd3';
        return;
      }

      // Double paket
      if (cancelScannedSet.has(resi)) {
        playScanVoice('double');
        resultBox.innerHTML = `
          <div style="text-align:center;">
            <div style="font-size:28px;margin-bottom:4px;">⚠️</div>
            <div style="font-size:15px;font-weight:800;color:#92400e;">Double Paket!</div>
            <div style="font-size:12px;color:#94a3b8;margin-top:4px;font-family:monospace;">${resi}</div>
          </div>`;
        resultBox.style.background = '#fef3c7';
        resultBox.style.border     = '1.5px solid #fde68a';
        return;
      }

      cancelScannedSet.add(resi);

      if (cancelResiSet.has(resi)) {
        // Paket cancel ditemukan
        playScanVoice('cancel');
        resultBox.innerHTML = `
          <div style="text-align:center;">
            <div style="font-size:28px;margin-bottom:4px;">🚨</div>
            <div style="font-size:15px;font-weight:800;color:#dc2626;">Paket Cancel!</div>
            <div style="font-size:12px;color:#94a3b8;margin-top:4px;font-family:monospace;">${resi}</div>
          </div>`;
        resultBox.style.background = '#fee2e2';
        resultBox.style.border     = '1.5px solid #fca5a5';
      } else {
        // Resi valid (JNT, ada di daftar, bukan cancel)
        playScanVoice('valid');
        resultBox.innerHTML = `
          <div style="text-align:center;">
            <div style="font-size:28px;margin-bottom:4px;">✅</div>
            <div style="font-size:15px;font-weight:800;color:#16a34a;">Paket Valid</div>
            <div style="font-size:12px;color:#94a3b8;margin-top:4px;font-family:monospace;">${resi}</div>
          </div>`;
        resultBox.style.background = '#f0fdf4';
        resultBox.style.border     = '1.5px solid #86efac';
      }

      updateCancelCounts();
    }

    function closeLacakCancel() {
      document.getElementById('cancel-modal').style.display = 'none';
      // Reset result box
      document.getElementById('cancel-last-result').innerHTML = `
        <div style="text-align:center;color:#94a3b8;">
          <div style="font-size:32px;margin-bottom:6px;">📦</div>
          <div style="font-size:13px;font-weight:600;">Siap scan resi...</div>
          <div style="font-size:11px;margin-top:3px;opacity:.7;">JY/JX = JNT · Lainnya = tidak valid</div>
        </div>`;
      document.getElementById('cancel-last-result').style.background = '#f8fafc';
      document.getElementById('cancel-last-result').style.border = '1.5px solid #e2e8f0';
    }

